var DE_TYPES={sampul:'Sampul Rapor',sekolah:'Identitas Sekolah',murid:'Identitas Peserta Didik'};
var DE_DEFAULT={
 sampul:'<div style="text-align:center;padding-top:35mm"><h2 style="letter-spacing:3px">LAPORAN HASIL BELAJAR</h2><h1 style="font-size:34pt;letter-spacing:5px">RAPOR</h1><h3>{{jenjang}}</h3><p><img src="{{logo}}" style="width:110pt;height:110pt;object-fit:contain"></p><p>NAMA MURID</p><h2>{{nama_murid}}</h2><p>NISN / NIS</p><h3>{{nisn}} / {{nis}}</h3><h2>{{nama_sekolah}}</h2><p>{{instansi_sampul}}</p></div>',
 sekolah:'<div style="text-align:center"><h2>IDENTITAS SEKOLAH</h2><h3>{{jenjang}}</h3></div><table style="width:100%;border-collapse:collapse" border="0" cellpadding="7"><tr><td>Nama Sekolah</td><td>:</td><td>{{nama_sekolah}}</td></tr><tr><td>NPSN</td><td>:</td><td>{{npsn}}</td></tr><tr><td>NIS/NSS/NDS</td><td>:</td><td>{{nss}}</td></tr><tr><td>Alamat Sekolah</td><td>:</td><td>{{alamat_sekolah}}</td></tr><tr><td>Kode Pos</td><td>:</td><td>{{kode_pos}}</td></tr><tr><td>Telepon</td><td>:</td><td>{{telepon}}</td></tr><tr><td>Desa/Kelurahan</td><td>:</td><td>{{desa}}</td></tr><tr><td>Kecamatan</td><td>:</td><td>{{kecamatan}}</td></tr><tr><td>Kabupaten/Kota</td><td>:</td><td>{{kabupaten}}</td></tr><tr><td>Provinsi</td><td>:</td><td>{{provinsi}}</td></tr><tr><td>Website</td><td>:</td><td>{{website}}</td></tr><tr><td>E-mail</td><td>:</td><td>{{email}}</td></tr></table>',
 murid:'<div style="text-align:center"><h2>IDENTITAS PESERTA DIDIK</h2></div><table style="width:100%;border-collapse:collapse" border="0" cellpadding="6"><tr><td>Nama Lengkap</td><td>:</td><td>{{nama_murid}}</td></tr><tr><td>NISN / NIS</td><td>:</td><td>{{nisn}} / {{nis}}</td></tr><tr><td>Tempat, Tanggal Lahir</td><td>:</td><td>{{ttl}}</td></tr><tr><td>Jenis Kelamin</td><td>:</td><td>{{jk}}</td></tr><tr><td>Agama</td><td>:</td><td>{{agama}}</td></tr><tr><td>Pendidikan Sebelumnya</td><td>:</td><td>{{pendidikan_sebelumnya}}</td></tr><tr><td>Alamat</td><td>:</td><td>{{alamat}}</td></tr><tr><td>Nama Ayah</td><td>:</td><td>{{nama_ayah}}</td></tr><tr><td>Nama Ibu</td><td>:</td><td>{{nama_ibu}}</td></tr><tr><td>Pekerjaan Ayah</td><td>:</td><td>{{pekerjaan_ayah}}</td></tr><tr><td>Pekerjaan Ibu</td><td>:</td><td>{{pekerjaan_ibu}}</td></tr><tr><td>Alamat Orang Tua</td><td>:</td><td>{{alamat_ortu}}</td></tr><tr><td>Nama Wali</td><td>:</td><td>{{nama_wali}}</td></tr></table><p style="text-align:right;margin-top:45mm">{{tempat}}, {{tanggal_rapor}}<br>Kepala Sekolah,<br><br><br><b>{{kepala_sekolah}}</b><br>{{nip_kepala}}</p>'
};
function deRead(){try{return JSON.parse(localStorage.getItem(DE_KEY)||'{}')}catch(e){return {}}}
function deWrite(x){localStorage.setItem(DE_KEY,JSON.stringify(x))}
function deClean(html){var box=document.createElement('div');box.innerHTML=String(html||'');box.querySelectorAll('script,iframe,object,embed,form').forEach(function(x){x.remove()});box.querySelectorAll('*').forEach(function(el){Array.from(el.attributes).forEach(function(a){if(/^on/i.test(a.name)||(/^(href|src)$/i.test(a.name)&&/^javascript:/i.test(a.value)))el.removeAttribute(a.name)})});return box.innerHTML}
function deValues(type,m){m=m||S.d.murid[0]||{};var p={nama_sekolah:P('nama_sekolah'),kelas:P('kelas'),semester:teksSemester(),tahun_pelajaran:P('tahun_pelajaran'),npsn:P('npsn'),nss:P('nss'),alamat_sekolah:P('alamat_sekolah'),kode_pos:P('kode_pos'),telepon:P('telepon'),desa:P('desa'),kecamatan:P('kecamatan'),kabupaten:P('kabupaten'),provinsi:P('provinsi'),website:P('website'),email:P('email'),logo:P('logo'),jenjang:teksJenjang(),instansi_sampul:P('instansi_sampul'),nama_murid:namaCetak(m),nisn:m.nisn||'',nis:m.nis||'',ttl:ttlMurid(m),jk:/^p/i.test(m.jk||'')?'Perempuan':/^l/i.test(m.jk||'')?'Laki-Laki':'',agama:m.agama||'',pendidikan_sebelumnya:m.pendidikan_sebelumnya||'',alamat:m.alamat||'',nama_ayah:m.nama_ayah||'',nama_ibu:m.nama_ibu||'',pekerjaan_ayah:m.pekerjaan_ayah||'',pekerjaan_ibu:m.pekerjaan_ibu||'',alamat_ortu:m.alamat_ortu||'',nama_wali:m.nama_wali||'',tempat:P('tempat_rapor')||P('kabupaten'),tanggal_rapor:tglIndo(P('tanggal_rapor')),kepala_sekolah:P('kepala_sekolah'),nip_kepala:P('nip_kepala')};return p}
function deRender(type,m){var cfg=deRead()[type];if(!cfg||!cfg.html)return null;var html=deClean(cfg.html),v=deValues(type,m);if(cfg.mode!=='manual')Object.keys(v).forEach(function(k){var val=String(v[k]==null?'':v[k]);if(k==='logo'){html=html.replace(/src="\{\{logo\}\}"/g,'src="'+val.replace(/"/g,'&quot;')+'"')}else html=html.replace(new RegExp('\\{\\{'+k+'\\}\\}','g'),esc(val))});var cfg=deRead()[type]||{};var paper=cfg.paper||P('kertas')||'A4';var orient=cfg.orientation||'portrait';return '<div class="page '+(paper==='F4'?'f4':'')+' '+(orient==='landscape'?'land':'')+' de-printed" style="font-family:Arial,sans-serif">'+html+'</div>'}
// Editor UI
VIEWS.editorDokumen=function(v){var all=deRead(),type='sampul',mode='otomatis',selected=(S.d.murid[0]||{}).id||'';function tpl(t){return (deRead()[t]&&deRead()[t].html)||DE_DEFAULT[t]}
v.innerHTML='<div class="row" style="align-items:center;margin-bottom:14px"><div><h2 style="margin:0">Editor Dokumen</h2><div class="muted small">Atur desain tiga halaman identitas secara terpisah dari data rapor.</div></div><span class="sp"></span><button class="btn ghost" id="deReset">Pulihkan desain bawaan</button><button class="btn" id="deSave">Simpan Desain</button></div><div class="de-wrap"><div class="card de-side"><div class="card-b"><div class="field"><label>Dokumen yang diedit</label><select class="inp" id="deType"><option value="sampul">Sampul Rapor</option><option value="sekolah">Identitas Sekolah</option><option value="murid">Identitas Peserta Didik</option></select></div><div class="field"><label>Mode dokumen</label><div class="de-mode"><button class="btn" id="deAuto">Otomatis</button><button class="btn ghost" id="deManual">Manual</button></div></div><div class="field" id="deStudentField"><label>Contoh data peserta didik</label><select class="inp" id="deStudent">'+S.d.murid.map(function(m){return '<option value="'+esc(m.id)+'">'+esc(m.nama)+'</option>'}).join('')+'</select></div><div class="field"><label>Ukuran kertas</label><select class="inp" id="dePaper"><option>A4</option><option>F4</option></select></div><div class="field"><label>Orientasi</label><select class="inp" id="deOrient"><option value="portrait">Potret</option><option value="landscape">Lanskap</option></select></div><div class="field"><label>Margin halaman (mm)</label><input class="inp" id="deMargin" type="number" min=5 max=35 value=20></div><p class="de-help">Mode Otomatis memakai placeholder seperti {{nama_sekolah}} dan {{nama_murid}} yang terhubung ke data aplikasi. Mode Manual memungkinkan seluruh isi diubah tanpa mengubah data asli.</p><div class="de-help"><b>Placeholder tersedia:</b><br>{{nama_sekolah}}, {{nama_murid}}, {{nisn}}, {{nis}}, {{kelas}}, {{semester}}, {{tahun_pelajaran}}, {{logo}}, dan data identitas lainnya.</div></div></div><div class="card"><div class="card-h"><b id="deTitle">Sampul Rapor</b><span class="sp"></span><span class="pill">Pratinjau editor</span><label class="de-inline-label" for="deZoom">Zoom</label><select id="deZoom" title="Perbesaran halaman"><option value="20">20%</option><option value="50">50%</option><option value="75" selected>75%</option><option value="100">100%</option></select></div><div class="card-b"><div class="de-tools"><select id="deFont" title="Jenis huruf"><option>Arial</option><option>Calibri</option><option>Times New Roman</option><option>Georgia</option><option>Verdana</option><option>Tahoma</option></select><select id="deSize" title="Ukuran huruf"><option>9</option><option>10</option><option>11</option><option selected>12</option><option>14</option><option>16</option><option>18</option><option>24</option><option>32</option></select><button data-cmd="bold"><b>B</b></button><button data-cmd="italic"><i>I</i></button><button data-cmd="underline"><u>U</u></button><input type="color" id="deColor" title="Warna teks" value="#111111"><button data-cmd="justifyLeft">☰</button><button data-cmd="justifyCenter">≡</button><button data-cmd="justifyRight">☷</button><button data-cmd="insertUnorderedList">• List</button><button id="deImage">＋ Gambar</button><label class="de-inline-label" for="deImgWidth">Lebar gambar (mm)</label><input id="deImgWidth" type="number" min="5" max="190" step="1" value="45" title="Lebar gambar dalam milimeter"><button id="deImgLeft" title="Posisi kiri">⇤</button><button id="deImgCenter" title="Posisi tengah">↔</button><button id="deImgRight" title="Posisi kanan">⇥</button><label class="de-inline-label" for="deImgTop">Jarak atas (mm)</label><input id="deImgTop" type="number" min="0" max="100" step="1" value="0" title="Jarak atas gambar"><button id="deTable">▦ Tabel</button><button id="deLine">― Garis</button><button id="deBox">▢ Kotak Teks</button><button id="deUndo">↶</button><button id="deRedo">↷</button></div><div class="de-sheet-wrap"><div id="deSheet" class="de-sheet" contenteditable="true" spellcheck="true"></div></div><input type="file" id="deImageFile" accept="image/png,image/jpeg,image/webp" hidden></div></div></div>';
var sheet=$('#deSheet',v),selectedImage=null;function active(){return S.d.murid.find(function(m){return String(m.id)===String(selected)})||S.d.murid[0]||{}}function paint(){var c=deRead()[type];selectedImage=null;sheet.innerHTML=deRender(type,active())?deRender(type,active()).replace(/^<div class="page [^"]*"[^>]*>|<\/div>$/g,''):tpl(type);sheet.contentEditable=mode==='manual'?'true':'true';sheet.style.fontFamily=$('#deFont',v).value;sheet.style.fontSize=$('#deSize',v).value+'pt';sheet.classList.toggle('f4',$('#dePaper',v).value==='F4');sheet.style.padding=Math.max(5,Math.min(35,Number($('#deMargin',v).value)||20))+'mm';applyZoom();syncImageControls();if($('#deOrient',v).value==='landscape'){sheet.style.width='297mm';sheet.style.minHeight='210mm'}else{sheet.style.width=$('#dePaper',v).value==='F4'?'215mm':'210mm';sheet.style.minHeight=$('#dePaper',v).value==='F4'?'330mm':'297mm'}$('#deTitle',v).textContent=DE_TYPES[type];$('#deStudentField',v).style.display=type==='murid'||type==='sampul'?'block':'none';$('#deAuto',v).classList.toggle('ghost',mode!=='otomatis');$('#deManual',v).classList.toggle('ghost',mode!=='manual')}
function applyZoom(){var z=Number($('#deZoom',v).value||75)/100;sheet.style.zoom=String(z)}
function syncImageControls(){var on=!!selectedImage;['deImgWidth','deImgTop','deImgLeft','deImgCenter','deImgRight'].forEach(function(id){$('#'+id,v).disabled=!on});if(on){var w=selectedImage.getBoundingClientRect().width;var mm=parseFloat(selectedImage.style.width);if(!mm&&w)mm=w*25.4/96;$('#deImgWidth',v).value=Math.max(5,Math.round(mm||45));$('#deImgTop',v).value=parseFloat(selectedImage.dataset.marginTopMm||'0')}}
function setImageAlign(align){if(!selectedImage)return;selectedImage.style.display='block';selectedImage.style.float='none';selectedImage.style.marginLeft=align==='left'?'0':align==='right'?'auto':'auto';selectedImage.style.marginRight=align==='right'?'0':align==='left'?'auto':'auto';if(align==='center'){selectedImage.style.marginLeft='auto';selectedImage.style.marginRight='auto'}selectedImage.dataset.align=align}
sheet.addEventListener('click',function(e){var img=e.target.closest('img');if(img&&sheet.contains(img)){if(selectedImage)selectedImage.classList.remove('de-img-selected');selectedImage=img;selectedImage.classList.add('de-img-selected');syncImageControls()}else if(selectedImage){selectedImage.classList.remove('de-img-selected');selectedImage=null;syncImageControls()}});
$('#deImgWidth',v).onchange=function(){if(!selectedImage)return;var n=Math.max(5,Math.min(190,Number(this.value)||45));selectedImage.style.width=n+'mm';selectedImage.style.maxWidth='100%';selectedImage.style.height='auto'};
$('#deImgTop',v).onchange=function(){if(!selectedImage)return;var n=Math.max(0,Math.min(100,Number(this.value)||0));selectedImage.dataset.marginTopMm=String(n);selectedImage.style.marginTop=n+'mm'};
$('#deImgLeft',v).onclick=function(){setImageAlign('left')};$('#deImgCenter',v).onclick=function(){setImageAlign('center')};$('#deImgRight',v).onclick=function(){setImageAlign('right')};$('#deZoom',v).onchange=applyZoom;
$('#deType',v).onchange=function(){type=this.value;paint()};$('#deStudent',v).onchange=function(){selected=this.value;paint()};$('#deAuto',v).onclick=function(){mode='otomatis';paint()};$('#deManual',v).onclick=function(){mode='manual';paint()};$('#dePaper',v).onchange=paint;$('#deOrient',v).onchange=paint;$('#deFont',v).onchange=function(){document.execCommand('fontName',false,this.value)};$('#deSize',v).onchange=function(){document.execCommand('fontSize',false,'7');$$('font[size="7"]',sheet).forEach(function(x){x.removeAttribute('size');x.style.fontSize=this.value+'pt'}.bind(this))};$('#deColor',v).oninput=function(){document.execCommand('foreColor',false,this.value)};
$$('[data-cmd]',v).forEach(function(b){b.onclick=function(){sheet.focus();document.execCommand(b.dataset.cmd,false,null)}});$('#deTable',v).onclick=function(){var rr=Math.max(1,Math.min(15,Number(prompt('Jumlah baris tabel:', '3'))||3)),cc=Math.max(1,Math.min(8,Number(prompt('Jumlah kolom tabel:', '2'))||2)),h='<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%">';for(var ri=0;ri<rr;ri++){h+='<tr>';for(var ci=0;ci<cc;ci++)h+='<td>&nbsp;</td>';h+='</tr>'}sheet.focus();document.execCommand('insertHTML',false,h+'</table><p></p>')};$('#deLine',v).onclick=function(){sheet.focus();document.execCommand('insertHTML',false,'<hr style="border:0;border-top:1px solid #555;margin:12px 0">')};$('#deBox',v).onclick=function(){sheet.focus();document.execCommand('insertHTML',false,'<div style="display:inline-block;min-width:120px;min-height:45px;padding:10px;border:1px solid #555;margin:5px">Kotak teks</div>')};$('#deMargin',v).onchange=function(){var n=Math.max(5,Math.min(35,Number(this.value)||20));sheet.style.padding=n+'mm'};$('#deUndo',v).onclick=function(){document.execCommand('undo')};$('#deRedo',v).onclick=function(){document.execCommand('redo')};$('#deImage',v).onclick=function(){$('#deImageFile',v).click()};$('#deImageFile',v).onchange=function(){var f=this.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Ukuran gambar maksimal 5 MB.','err');return}var r=new FileReader();r.onload=function(){sheet.focus();document.execCommand('insertHTML',false,'<img src="'+r.result+'" data-align="center" data-margin-top-mm="0" style="display:block;width:45mm;max-width:100%;height:auto;object-fit:contain;margin-left:auto;margin-right:auto">')};r.readAsDataURL(f);this.value='';selectedImage=null;syncImageControls()};
$('#deSave',v).onclick=function(){var d=deRead();var saveBox=document.createElement('div');saveBox.innerHTML=sheet.innerHTML;saveBox.querySelectorAll('.de-img-selected').forEach(function(img){img.classList.remove('de-img-selected')});d[type]={html:deClean(saveBox.innerHTML),paper:$('#dePaper',v).value,orientation:$('#deOrient',v).value,mode:mode,updated:new Date().toISOString()};try{deWrite(d);toast('Desain '+DE_TYPES[type]+' berhasil disimpan.')}catch(e){toast('Gagal menyimpan desain: '+e.message,'err')}};$('#deReset',v).onclick=function(){konfirmasi('Pulihkan desain bawaan','Desain tersimpan untuk dokumen ini akan dihapus.','Pulihkan',true).then(function(ok){if(!ok)return;var d=deRead();delete d[type];deWrite(d);paint();toast('Desain bawaan dipulihkan.')})};paint();};
// Gunakan template tersimpan untuk keluaran cetak/PDF tanpa menyentuh data utama.
var deHalamanSampulAsli=halamanSampul,deHalamanSekolahAsli=halamanIdentitasSekolah,deHalamanMuridAsli=halamanIdentitasMurid;
halamanSampul=function(m){return deRender('sampul',m)||deHalamanSampulAsli(m)};
halamanIdentitasSekolah=function(){return deRender('sekolah',S.d.murid[0])||deHalamanSekolahAsli()};
halamanIdentitasMurid=function(m){return deRender('murid',m)||deHalamanMuridAsli(m)};
